#!/usr/bin/env node
// Regenerate the bundled lifecycle artifacts in bin/ from this repo's own src/.
//
// The lifecycle source lives at src/ (restored from the deleted shared package);
// esbuild bundles it directly from TypeScript into self-contained ESM bundles.
// The COMMITTED bin/*.js are the distributable — run this after any change to
// src/ and commit the regenerated bytes alongside the source diff.

import { build } from "esbuild";
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.dirname(path.dirname(fileURLToPath(import.meta.url)));

const entries = {
  "librarian-claude-hook": path.join(root, "src", "bin", "claude-code-hook.ts"),
  "librarian-mcp-call": path.join(root, "src", "bin", "mcp-call.ts"),
};

for (const [name, entryPoint] of Object.entries(entries)) {
  await build({
    entryPoints: [entryPoint],
    outfile: path.join(root, "bin", `${name}.js`),
    bundle: true,
    platform: "node",
    format: "esm",
    target: "node18",
    // No shebang banner: esbuild already hoists the entry file's shebang, and the
    // bins are always run as `node <bin>` (dispatch.sh / spawnSync), so the
    // shebang is cosmetic. A banner here would duplicate it and break `node --check`.
    legalComments: "none",
  });
  console.log(`bundled bin/${name}.js`);
}

// Stamp provenance so the committed artifacts are auditable and drift-checkable:
// validate.mjs (run in CI) asserts each bin still matches the recorded hash, so a
// hand-edited or stale bin fails CI. The repoSha records WHICH source produced
// these bytes (CI can't rebuild without committing source-diff + bins together).
function sha256(file) {
  return createHash("sha256").update(readFileSync(file)).digest("hex");
}
function tryExec(cmd, args) {
  try {
    return execFileSync(cmd, args, { encoding: "utf8" }).trim();
  } catch {
    return "unknown";
  }
}
const provenance = {
  source: "in-tree",
  repoSha: tryExec("git", ["-C", root, "rev-parse", "HEAD"]),
  bins: Object.fromEntries(
    Object.keys(entries).map((name) => [`${name}.js`, sha256(path.join(root, "bin", `${name}.js`))]),
  ),
};
writeFileSync(
  path.join(root, "bin", "PROVENANCE.json"),
  `${JSON.stringify(provenance, null, 2)}\n`,
);
console.log(`wrote bin/PROVENANCE.json (repo ${provenance.repoSha.slice(0, 12)})`);
